use std::sync::Arc;

use crate::{PixelFormat, VncError};

type ImageData = Vec<u8>;

/// A rect where the image should be updated
#[derive(Debug, Clone, Copy)]
pub struct Rect {
    pub x: u16,
    pub y: u16,
    pub width: u16,
    pub height: u16,
}

/// Resolution format to resize window
#[derive(Debug, Clone)]
pub struct Screen {
    pub width: u16,
    pub height: u16,
}

impl From<(u16, u16)> for Screen {
    fn from(tuple: (u16, u16)) -> Self {
        Self {
            width: tuple.0,
            height: tuple.1,
        }
    }
}

/// One screen of an RFB ExtendedDesktopSize layout (termiHub fork, #3463).
///
/// ```text
/// +--------------+--------------+-------------+
/// | No. of bytes | Type [Value] | Description |
/// +--------------+--------------+-------------+
/// | 4            | U32          | id          |
/// | 2            | U16          | x-position  |
/// | 2            | U16          | y-position  |
/// | 2            | U16          | width       |
/// | 2            | U16          | height      |
/// | 4            | U32          | flags       |
/// +--------------+--------------+-------------+
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct DesktopScreen {
    pub id: u32,
    pub x: u16,
    pub y: u16,
    pub width: u16,
    pub height: u16,
    pub flags: u32,
}

/// Why the server sent an ExtendedDesktopSize rectangle (its `x-position`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DesktopSizeReason {
    /// The server changed the size itself (or reports the initial layout).
    Server,
    /// The reply to this client's own `SetDesktopSize`.
    Client,
    /// Another client resized the desktop.
    OtherClient,
    /// A reason code this client does not know.
    Unknown(u16),
}

impl From<u16> for DesktopSizeReason {
    fn from(value: u16) -> Self {
        match value {
            0 => Self::Server,
            1 => Self::Client,
            2 => Self::OtherClient,
            other => Self::Unknown(other),
        }
    }
}

/// The result of a `SetDesktopSize` request (the rectangle's `y-position`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DesktopSizeStatus {
    /// No error: the framebuffer and layout in the rectangle are in effect.
    Ok,
    /// The server does not allow clients to resize the desktop.
    Prohibited,
    /// The server lacks the resources for the requested size.
    OutOfResources,
    /// The requested screen layout is invalid.
    InvalidLayout,
    /// A status code this client does not know (always a refusal).
    Unknown(u16),
}

impl From<u16> for DesktopSizeStatus {
    fn from(value: u16) -> Self {
        match value {
            0 => Self::Ok,
            1 => Self::Prohibited,
            2 => Self::OutOfResources,
            3 => Self::InvalidLayout,
            other => Self::Unknown(other),
        }
    }
}

/// A server ExtendedDesktopSize pseudo-rectangle (encoding -308, termiHub
/// fork, #3463): the framebuffer size and screen layout, why they were sent,
/// and — for a reply to this client's `SetDesktopSize` — whether the request
/// was honoured. With a non-[`DesktopSizeStatus::Ok`] status the size and
/// layout are informational only; the framebuffer did not change.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ExtendedDesktopSize {
    pub reason: DesktopSizeReason,
    pub status: DesktopSizeStatus,
    pub width: u16,
    pub height: u16,
    pub screens: Vec<DesktopScreen>,
}

/// A client `SetDesktopSize` request (RFB message 251, termiHub fork, #3463).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DesktopSizeRequest {
    pub width: u16,
    pub height: u16,
    pub screens: Vec<DesktopScreen>,
}

type SrcRect = Rect;
type DstRect = Rect;

/// Events generated by the [crate::VncClient]
///
#[non_exhaustive]
#[derive(Debug, Clone)]
pub enum VncEvent {
    /// Tell the client how to display the images
    ///
    /// ```no_compile
    /// if let VncEvent::SetResolution(resolution) = event {
    ///     window.resize(screen.width, screen.height);
    /// }
    /// ```
    ///
    /// Note that this event may be recived multiple times
    ///
    /// If the [crate::VncEncoding::DesktopSizePseudo] is set
    ///
    SetResolution(Screen),
    /// If the connector doesn't call `set_pixel_format` method
    ///
    /// The engine will generate a [VncEvent::SetPixelFormat] to let the window know how to render image
    ///
    SetPixelFormat(PixelFormat),
    /// Raw image data in the order followed by informed PixelFormat
    ///
    RawImage(Rect, ImageData),
    /// Copy image data from the second rect to the first
    ///
    Copy(DstRect, SrcRect),
    /// A jpeg image if using Tight encoding,
    ///
    /// Encoding the bytes with base64 and render it with "<img src=data:image/jpeg;base64,.../>",
    ///
    JpegImage(Rect, ImageData),

    // PngImage(Rect, ImageData),
    /// Will be generated if [crate::VncEncoding::CursorPseudo] is set
    ///
    /// According to [RFC6143, section-7.8.1](https://www.rfc-editor.org/rfc/rfc6143.html#section-7.8.1)
    ///
    /// The rect's `x`/`y` are the hotspot. termiHub fork (#3464): the data is
    /// always RGBA8888 (`width * height * 4` bytes, alpha from the cursor mask),
    /// independent of the negotiated pixel format.
    ///
    SetCursor(Rect, ImageData),
    /// Just ring a bell
    ///
    Bell,
    /// Will be generated everytime the vncserver's clipboarded get updated
    ///
    /// Note that only Latin-1 character set is allowed
    ///
    /// According to [RFC6143](https://www.rfc-editor.org/rfc/rfc6143.html#section-7.6.4)
    ///
    Text(String),
    /// The server's ExtendedDesktopSize layout (termiHub fork, #3463): sent
    /// only when [crate::VncEncoding::ExtendedDesktopSizePseudo] was
    /// negotiated — first with the initial layout, then on every server- or
    /// client-initiated change and as the reply to [X11Event::SetDesktopSize].
    /// A size change with status `Ok` is also reported as
    /// [VncEvent::SetResolution].
    DesktopLayout(ExtendedDesktopSize),
    /// ExtendedDesktopSize was negotiated but the server's first
    /// `FramebufferUpdate` carried no layout rectangle, so the server does not
    /// support it and `SetDesktopSize` must not be sent (termiHub fork, #3463).
    /// Emitted at most once.
    DesktopLayoutUnsupported,
    /// If any unexpected error happens in the async process routines
    /// This event will propagate the error to the current context
    ///
    /// termiHub fork (#3479): carries the typed [`VncError`] (shared, since
    /// `VncError` is not `Clone`) instead of its rendered text, so a consumer
    /// can tell a server protocol violation from a transport failure without
    /// parsing the message. A caught internal panic is [`VncError::Internal`].
    Error(Arc<VncError>),
}

/// X11 keyboard event to notify the server
///
/// Referring to [RFC6143, section-7.5.4](https://www.rfc-editor.org/rfc/rfc6143.html#section-7.5.4)
///
#[derive(Debug, Clone)]
pub struct ClientKeyEvent {
    pub keycode: u32,
    pub down: bool,
}

impl From<(u32, bool)> for ClientKeyEvent {
    fn from(tuple: (u32, bool)) -> Self {
        Self {
            keycode: tuple.0,
            down: tuple.1,
        }
    }
}

/// X11 mouse event to notify the server
///
/// Referring to [RFC6143, seciont-7.5.5](https://www.rfc-editor.org/rfc/rfc6143.html#section-7.5.5)
///
#[derive(Debug, Clone)]
pub struct ClientMouseEvent {
    pub position_x: u16,
    pub position_y: u16,
    pub bottons: u8,
}

impl From<(u16, u16, u8)> for ClientMouseEvent {
    fn from(tuple: (u16, u16, u8)) -> Self {
        Self {
            position_x: tuple.0,
            position_y: tuple.1,
            bottons: tuple.2,
        }
    }
}

/// Client-side event which used to ask the engine send some command to the vnc server
///
#[non_exhaustive]
#[derive(Debug, Clone)]
pub enum X11Event {
    /// Require an incremental frame update
    ///
    Refresh,
    /// Require a full (non-incremental) frame update.
    /// Forces the server to send the entire framebuffer, useful after
    /// CursorPseudo is negotiated to clear cursor ghosts from the framebuffer.
    FullRefresh,
    /// Key down/up
    ///
    KeyEvent(ClientKeyEvent),
    /// Mouse move/up/down/scroll
    ///
    PointerEvent(ClientMouseEvent),
    /// Send data to the server's clipboard
    ///
    /// Only Latin-1 character set is allowed
    ///
    CopyText(String),
    /// Ask the server to resize the desktop (RFB `SetDesktopSize`, termiHub
    /// fork, #3463). Only valid once the server has sent a
    /// [VncEvent::DesktopLayout]; the reply arrives as another one with
    /// [DesktopSizeReason::Client].
    SetDesktopSize(DesktopSizeRequest),
}
